/**
 * Anonymous telemetry for StakeStats PRO extension.
 * All data is anonymized - no PII is collected.
 */

const TELEMETRY_URL = "https://linearntrack.com/api/telemetry";
const DEVICE_ID_KEY = "telemetry_device_id";
const LAST_OPENED_KEY = "telemetry_last_opened";
const EXTENSION_VERSION = "1.0.0";

/**
 * Get or generate a unique device ID (anonymous, not tied to any PII)
 */
async function getDeviceId() {
  const result = await chrome.storage.local.get(DEVICE_ID_KEY);
  if (result[DEVICE_ID_KEY]) {
    return result[DEVICE_ID_KEY];
  }

  // Generate new device ID
  const deviceId = `dev_${Date.now()}_${Math.random().toString(36).substring(2, 10)}`;
  await chrome.storage.local.set({ [DEVICE_ID_KEY]: deviceId });
  return deviceId;
}

/**
 * Send a telemetry event
 * @param {string} event - Event name
 * @param {object} data - Optional event data
 */
async function track(event, data = null) {
  try {
    const deviceId = await getDeviceId();

    const response = await fetch(TELEMETRY_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        deviceId,
        event,
        data,
        version: EXTENSION_VERSION,
      }),
    });

    if (!response.ok) {
      console.debug(`Telemetry failed: ${response.status}`);
    }
  } catch (e) {
    // Silently fail - telemetry should never break the extension
    console.debug("Telemetry error:", e.message);
  }
}

/**
 * Track extension install (called once on first run)
 */
async function trackInstall() {
  const result = await chrome.storage.local.get("telemetry_installed");
  if (!result.telemetry_installed) {
    await track("extension_installed");
    await chrome.storage.local.set({ telemetry_installed: true });
  }
}

/**
 * Track popup opened (daily unique)
 */
async function trackPopupOpened() {
  const today = new Date().toISOString().split("T")[0];
  const result = await chrome.storage.local.get(LAST_OPENED_KEY);

  if (result[LAST_OPENED_KEY] !== today) {
    await track("extension_opened");
    await chrome.storage.local.set({ [LAST_OPENED_KEY]: today });
  }
}

/**
 * Track game detection
 * @param {string} game - Game type (keno, dice)
 */
async function trackGameDetected(game) {
  await track("game_detected", { game });
}

/**
 * Track round tracked (batched - only send periodically)
 * @param {string} game - Game type
 */
let roundCount = 0;
async function trackRound(game) {
  roundCount++;
  // Only send every 100 rounds to reduce API calls
  if (roundCount % 100 === 0) {
    await track("round_tracked", { game, count: 100 });
  }
}

/**
 * Track PRO activation
 */
async function trackProActivated() {
  await track("pro_activated");
}

/**
 * Track PRO expiration
 */
async function trackProExpired() {
  await track("pro_expired");
}

/**
 * Track AI picks viewed
 */
async function trackAiPicksViewed() {
  await track("ai_picks_viewed");
}

/**
 * Track autofill used
 */
async function trackAutofillUsed() {
  await track("autofill_used");
}

/**
 * Track heatmap opened
 * @param {string} game - Game type
 */
async function trackHeatmapOpened(game) {
  await track("heatmap_opened", { game });
}

/**
 * Track errors
 * @param {string} errorMessage - Error message
 * @param {string} context - Where the error occurred
 */
async function trackError(errorMessage, context) {
  await track("error", { message: errorMessage, context });
}

export {
  trackInstall,
  trackPopupOpened,
  trackGameDetected,
  trackRound,
  trackProActivated,
  trackProExpired,
  trackAiPicksViewed,
  trackAutofillUsed,
  trackHeatmapOpened,
  trackError,
};
